import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  KeyboardAvoidingView,
  Modal,
  Platform,
  TouchableOpacity,
  View,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import {Agreement} from '../../../../../model/interface/general-setting.interface';
import {IcBlackLeftArrow} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import ModalConfirm from '../../../../../components/ModalConfirm';
import {useGeneralSettingServices} from '../../../../../hook/apiHook/useApi';

type ModalSettingCertificateProp = {
  onClose: () => void;
  isVisible: boolean;
  data: Agreement;
  onPressChangePassword: () => void;
};

const ModalSettingCertificate = ({
  onClose,
  isVisible,
  data,
  onPressChangePassword,
}: ModalSettingCertificateProp) => {
  const {t} = useTranslation();

  const insets = useSafeAreaInsets();

  const [success, setSuccess] = useState(false);

  const [loading, setLoading] = useState(false);

  const GeneralSettingServices = useGeneralSettingServices();

  const handleResetPassword = async () => {
    try {
      setLoading(true);
      const res = await GeneralSettingServices.resetDigitalCertificatePassword(
        data.agreementUuid,
      );
      setSuccess(true);
    } catch (error) {
      onClose();
    } finally {
      setLoading(false);
    }
  };

  const handleChangePassword = () => {
    onPressChangePassword();
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <KeyboardAvoidingView
        style={styles.ctnContainer}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('ST.DigitalCertificate.settingDigitalCertificate')}
            </TextCM>
            <View />
          </View>
          <View style={styles.viewLabel}>
            <TextCM style={styles.txtLabel}>
              {t('ST.DigitalCertificate.digitalCertificate')}
            </TextCM>
            <TextCM style={styles.agreement}>{data.agreementUuid}</TextCM>
          </View>
          <View style={styles.viewBody}>
            <ButtonCM
              type="white"
              label={t('ST.DigitalCertificate.resetPassword')}
              onPress={handleResetPassword}
              loading={loading}
            />
            <ButtonCM
              type="white"
              label={t('ST.DigitalCertificate.changePassword')}
              onPress={handleChangePassword}
            />
          </View>
        </View>
      </KeyboardAvoidingView>
      <ModalConfirm
        type="success"
        onClose={onClose}
        isVisible={success}
        title={t('ST.DigitalCertificate.submittedCertificateSuccessfully')}
        content={t(
          'ST.DigitalCertificate.contentSubmittedCertificateSuccessfully',
        )}
      />
    </Modal>
  );
};

export default ModalSettingCertificate;
