import {Image, TouchableOpacity} from 'react-native';
import React, {useState} from 'react';
import styles from './styles';

import {useTranslation} from 'react-i18next';
import ModalAddImageSignature from '../ModalAddImageSignature';
import {IImageSignature} from '../../../../../services/interface';
import Toast from 'react-native-toast-message';
import {
  IconBlackFavorite,
  IconBlackPen,
  IconBlackTrash,
  IconBlueInfo,
  IconGreyTrash,
  IconMenuFavoriteActive,
  IconRedConfirmTrash,
} from '../../../../../assets/images';
import {SizeDP} from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';
import {View as ViewCM} from 'react-native';
import {String} from '../../../../../constants';
import ModalConfirm from '../../../../../components/ModalConfirm';
import { useAccountServices } from '../../../../../hook/apiHook/useApi';

type Props = {
  data: IImageSignature;
  onSuccess: () => void;
};

const ImageSignatureItem = ({data, onSuccess}: Props) => {
  const {t} = useTranslation();

  const accountServices = useAccountServices();
  const [modalConfirmFavorites, setModalConfirmFavorites] = useState(false);
  const [modalConfirmTrash, setModalConfirmTrash] = useState(false);
  const [modalAddEdit, setModalEdit] = useState(false);

  const toggleModalConfirmTrash = () => {
    setModalConfirmTrash(!modalConfirmTrash);
  };

  const toggleModalConfirmFavorites = () => {
    setModalConfirmFavorites(!modalConfirmFavorites);
  };

  const toggleModalEdit = () => {
    setModalEdit(!modalAddEdit);
  };

  const updateStar = async () => {
    toggleModalConfirmFavorites();
    const formData = new FormData();
    formData.append('dto', JSON.stringify({name: data.name, star: true}));
    try {
      const body = {
        id: data.id,
        data: formData,
      };
      const res = await accountServices.updateImageSignature(body);
      onSaveSuccess(t('AC.TxtFavoriteImageSignatureSuccess'));
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    }
  };

  const deleteItem = async () => {
    toggleModalConfirmTrash();
    try {
      const res = await accountServices.deleteImageSignature(data.id);
      onSaveSuccess(t('AC.TxtDeleteImageSignatureSuccess'));
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('CM.TxtSystemError'),
      });
    }
  };

  const onSaveSuccess = async (title: '') => {
    onSuccess();
    Toast.show({
      type: 'success',
      text1: title,
    });
  };

  const renderIconDelete = () => {
    return <IconRedConfirmTrash width={SizeDP(80)} height={SizeDP(78)} />;
  };

  const renderIconInfo = () => {
    return <IconBlueInfo width={SizeDP(80)} height={SizeDP(78)} />;
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM style={styles.header}>
        <TextCM style={styles.txtName} numberOfLines={1}>
          {data.name}
        </TextCM>
        <ViewCM style={styles.viewAction}>
          <TouchableOpacity onPress={toggleModalEdit}>
            <IconBlackPen width={SizeDP(18)} height={SizeDP(18)} />
          </TouchableOpacity>
          <TouchableOpacity
            disabled={data.star}
            onPress={toggleModalConfirmTrash}>
            {data.star ? (
              <IconGreyTrash width={SizeDP(18)} height={SizeDP(18)} />
            ) : (
              <IconBlackTrash width={SizeDP(18)} height={SizeDP(18)} />
            )}
          </TouchableOpacity>
          <TouchableOpacity
            disabled={data.star}
            onPress={toggleModalConfirmFavorites}>
            {data.star ? (
              <IconMenuFavoriteActive width={SizeDP(18)} height={SizeDP(18)} />
            ) : (
              <IconBlackFavorite width={SizeDP(18)} height={SizeDP(18)} />
            )}
          </TouchableOpacity>
        </ViewCM>
      </ViewCM>
      <ViewCM style={styles.body}>
        <Image
          style={styles.styleImage}
          source={{uri: String.PREFIX_IMG_BASE64 + data.signature}}
        />
      </ViewCM>
      <ModalConfirm
        title={t('AC.TxtFavoriteImageSignature')}
        content={t('AC.TxtDesFavoriteImageSignature')}
        onConfirm={updateStar}
        onClose={toggleModalConfirmFavorites}
        isVisible={modalConfirmFavorites}
        labelConfirm={t('CM.Agree')}
        renderIcon={renderIconInfo}
      />
      <ModalConfirm
        title={t('AC.TxtDeleteImageSignature')}
        content={t('AC.TxtContentDeleteImageSignature')}
        onConfirm={deleteItem}
        onClose={toggleModalConfirmTrash}
        isVisible={modalConfirmTrash}
        labelConfirm={t('CM.BtnClear')}
        renderIcon={renderIconDelete}
      />
      {modalAddEdit && (
        <ModalAddImageSignature
          isVisible={modalAddEdit}
          onClose={toggleModalEdit}
          type={'EDIT'}
          onSuccess={onSuccess}
          data={data}
        />
      )}
    </ViewCM>
  );
};

export default ImageSignatureItem;
