import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import TextCM from '../../../../../../../components/Text';
import {DateUtils} from '../../../../../../../utils';
import {IconGreyCalendar} from '../../../../../../../assets/images';
import ModalPicDate from '../../../../../../../components/ModalPicDate';

type Props = {
  label: string;
  date: any;
  onChangeDate: (date: any) => void;
  maxDate?: any;
  minDate?: any;
  title: string;
};

const PicDateView = ({
  date,
  label,
  onChangeDate,
  maxDate,
  minDate,
  title,
}: Props) => {
  const {t} = useTranslation();

  const [isShowModalPicDate, setIsShowModalPicDate] = useState(false);

  const toggleShowModalPicDate = () => {
    setIsShowModalPicDate(!isShowModalPicDate);
  };

  const onPicDate = (date: any) => {
    onChangeDate(date);
    setIsShowModalPicDate(false);
  };

  return (
    <>
      <TextCM style={styles.txtTitle}>{title}</TextCM>
      <TouchableOpacity
        style={styles.btnPicType}
        onPress={toggleShowModalPicDate}>
        {!date ? (
          <TextCM style={styles.txtNoDate}>{label}</TextCM>
        ) : (
          <View>
            <TextCM style={styles.txtSmallLabel}>{label}</TextCM>
            <TextCM style={styles.txtDate}>
              {DateUtils.convertDateToDDMMYYYY(date)}
            </TextCM>
          </View>
        )}
        <IconGreyCalendar width={16} height={16} />
      </TouchableOpacity>
      <ModalPicDate
        title={t('DC.modal.TxtPicDate')}
        isVisible={isShowModalPicDate}
        onClose={toggleShowModalPicDate}
        onSave={onPicDate}
        initDate={date}
        labelSave={t('CM.BtnConfirm')}
        maxDate={maxDate ? new Date(maxDate) : undefined}
        minDate={minDate ? new Date(minDate) : undefined}
      />
    </>
  );
};

export default PicDateView;
