import {isEmpty} from 'lodash';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TextInput, TouchableOpacity} from 'react-native';
import styles from './styles';
import { IconBlackClose, IconGreySearch } from '../../../../../assets/images';
import { Color } from '../../../../../constants';
import { View as ViewCM } from 'react-native';

type Props = {
  searchText: string;
  setSearchText: (text: string) => void;
};

const InputSearch = ({searchText, setSearchText}: Props) => {
  const {t} = useTranslation();

  const [isFocused, setIsFocused] = useState(false);

  const onPressIconRight = () => {
    setSearchText('');
  };

  return (
    <ViewCM style={styles.container}>
      <ViewCM
        style={[styles.viewInput, isFocused && {borderColor: Color.Primary}]}>
        <IconGreySearch width={24} height={24}/>
        <TextInput
          allowFontScaling={false}
          value={searchText}
          style={styles.textInput}
          placeholder={t('DC.TxtSearch')}
          placeholderTextColor={'#667085'}
          onChangeText={setSearchText}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
        />
        <TouchableOpacity style={styles.btnFilter} onPress={onPressIconRight}>
          {!isEmpty(searchText) && <IconBlackClose />}
        </TouchableOpacity>
      </ViewCM>
    </ViewCM>
  );
};

export default InputSearch;
