import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Modal, TouchableOpacity, View} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';

import {yupResolver} from '@hookform/resolvers/yup';
import {FormProvider, useForm} from 'react-hook-form';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import * as yup from 'yup';
import YupTextField from './components/YupTextField';
import {
  appearNumberChar,
  atleast8CharacterRegex,
  normalCharacterRegex,
  validationHint,
} from './helper';
import {Agreement} from '../../../../../model/interface/general-setting.interface';
import {
  IcBlackLeftArrow,
  IcGreyCircleX,
  IcSuccess,
} from '../../../../../assets/images';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import ModalConfirm from '../../../../../components/ModalConfirm';
import { useGeneralSettingServices } from '../../../../../hook/apiHook/useApi';

type ModalChangePasswordCertificateProp = {
  onClose: () => void;
  isVisible: boolean;
  data: Agreement;
};

const ModalChangePasswordCertificate = ({
  onClose,
  isVisible,
  data,
}: ModalChangePasswordCertificateProp) => {
  const {t} = useTranslation();

  const [loading, setLoading] = useState(false);

  const [success, setSuccess] = useState(false);

  const GeneralSettingServices = useGeneralSettingServices()

  const schema = yup.object().shape({
    currentPassword: yup
      .string()
      .min(4, t('ST.DigitalCertificate.atLeast4character'))
      .required(t('SU.fieldRequired')),
    newPassword: yup.string(),
    newReplacePassword: yup
      .string()
      .min(4, t('ST.DigitalCertificate.atLeast4character'))
      .test(
        'passwords-match',
        t('ST.DigitalCertificate.confirmPasswordsNotMatch'),
        function (value) {
          return value === this.parent.newPassword;
        },
      )
      .required(t('SU.fieldRequired')),
  });

  const methods = useForm({
    mode: 'onBlur',
    resolver: yupResolver(schema),
    defaultValues: {
      currentPassword: '',
      newPassword: '',
      newReplacePassword: '',
    },
  });

  const insets = useSafeAreaInsets();

  const valHint = validationHint(methods.watch('newPassword') ?? '', [
    {
      regex: appearNumberChar,
      message: t('ST.DigitalCertificate.atLeast1NumericCharacter'),
    },
    {
      regex: normalCharacterRegex,
      message: t('ST.DigitalCertificate.atLeast1LowercaseCharacter'),
    },
    {
      regex: atleast8CharacterRegex,
      message: t('ST.DigitalCertificate.minimumLength8Characters'),
    },
  ]);

  const isDisableButton =
    valHint.some(item => !item.pass) || !methods.formState.isValid;

  const renderHintext = () => {
    return (
      <View style={styles.viewHint}>
        {valHint.map((item, index) => {
          return (
            <View key={index} style={styles.itemHint}>
              {item.pass ? (
                <IcSuccess width={16} height={16} />
              ) : (
                <IcGreyCircleX width={16} height={16} />
              )}
              <TextCM style={styles.txtHint}>{item.message}</TextCM>
            </View>
          );
        })}
      </View>
    );
  };

  const handleConfirm = async () => {
    try {
      setLoading(true);
      const res = await GeneralSettingServices.changeDigitalCertificatePassword(
        data.agreementUuid,
        methods.getValues('newPassword') ?? '',
        methods.getValues('currentPassword'),
      );
      setSuccess(true);
    } catch (error) {
      onClose();
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <View style={styles.ctnContainer}>
        <View style={styles.ctnTop} onTouchEnd={onClose} />
        <View style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <View style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IcBlackLeftArrow width={14} height={16} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {t('ST.DigitalCertificate.changeDigitalCertificatePassword')}
            </TextCM>
            <View />
          </View>
          <KeyboardAwareScrollView>
            <FormProvider {...methods}>
              <View style={styles.viewBody}>
                <YupTextField
                  controlName={'currentPassword'}
                  label={t('ST.DigitalCertificate.currentPassword')}
                />
                <YupTextField
                  controlName={'newPassword'}
                  label={t('ST.DigitalCertificate.typeNewPassword')}
                />
                {renderHintext()}
                <YupTextField
                  controlName={'newReplacePassword'}
                  label={t('ST.DigitalCertificate.typeConfirmPassword')}
                />
              </View>
              <View style={styles.viewBody}>
                <ButtonCM
                  disabled={isDisableButton}
                  label={t('CM.BtnConfirm')}
                  onPress={handleConfirm}
                  loading={loading}
                />
              </View>
            </FormProvider>
          </KeyboardAwareScrollView>
        </View>
      </View>
      <ModalConfirm
        type="success"
        onClose={onClose}
        isVisible={success}
        title={t('ST.DigitalCertificate.changePasswordSuccessfully')}
        content=""
      />
    </Modal>
  );
};

export default ModalChangePasswordCertificate;
