import React, {FC, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {StyleProp, TouchableOpacity, View, ViewStyle} from 'react-native';
import ModalChangePasswordCertificate from '../ModalChangePasswordCertificate';
import ModalSettingCertificate from '../ModalSettingCertificate';
import styles from './styles';
import {Agreement} from '../../../../../model/interface/general-setting.interface';
import {useGeneralSettingServices} from '../../../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import TextCM from '../../../../../components/Text';
import {IcGreySetting, IcRedTrash} from '../../../../../assets/images';
import ModalConfirm from '../../../../../components/ModalConfirm';

type Props = {
  styleContainer?: StyleProp<ViewStyle>;
  data: Agreement;
  fetching: () => void;
};

const ItemDigitalCertificate: FC<Props> = ({
  styleContainer,
  data,
  fetching,
}) => {
  const {t} = useTranslation();

  const [showModal, setShowModal] = useState({
    changePasswordCertificate: false,
    settingCertificate: false,
    deleteModal: false,
  });

  const GeneralSettingServices = useGeneralSettingServices();

  const toggleModal = (type: string) => () => {
    switch (type) {
      case 'deleteModal':
        setShowModal(prev => ({...prev, deleteModal: !prev.deleteModal}));
        break;
      case 'settingCertificate':
        setShowModal(prev => ({
          ...prev,
          settingCertificate: !prev.settingCertificate,
        }));
        break;
      case 'changePasswordCertificate':
        setShowModal(prev => ({
          ...prev,
          changePasswordCertificate: !prev.changePasswordCertificate,
        }));
        break;
      default:
        break;
    }
  };

  const onPressChangePassword = () => {
    toggleModal('settingCertificate')();
    toggleModal('changePasswordCertificate')();
  };

  const handleDelete = async () => {
    try {
      const res = await GeneralSettingServices.deleteDigitalCertificate(
        data.id,
      );
      Toast.show({
        text1: t('CM.MessageDeleteSuccess'),
        type: 'success',
      });
    } catch (error) {
    } finally {
      toggleModal('deleteModal')();
      fetching();
    }
  };

  return (
    <View style={[styles.container, styleContainer]}>
      <View style={styles.viewTop}>
        <View style={styles.viewLabel}>
          <TextCM style={styles.xxSmallRegular}>
            {t('ST.DigitalCertificate.userName')}
          </TextCM>
          <TextCM style={styles.smallRegular}>{data.agreementUuid}</TextCM>
        </View>
        <View style={styles.viewIcon}>
          <TouchableOpacity onPress={toggleModal('settingCertificate')}>
            <IcGreySetting width={16} height={16} />
          </TouchableOpacity>
          <TouchableOpacity onPress={toggleModal('deleteModal')}>
            <IcRedTrash width={14} height={16} />
          </TouchableOpacity>
        </View>
      </View>
      <View style={styles.seperator} />
      <View style={styles.viewNote}>
        <TextCM style={styles.xxSmallRegular}>
          {t('ST.DigitalCertificate.note')}
        </TextCM>
        <TextCM style={styles.noteSmallRegular}>{data.caption}</TextCM>
      </View>
      <ModalConfirm
        isVisible={showModal.deleteModal}
        title={t('ST.DigitalCertificate.confirmDelete')}
        content={t('ST.DigitalCertificate.areYouDelete')}
        onClose={toggleModal('deleteModal')}
        onConfirm={handleDelete}
      />
      {showModal.changePasswordCertificate && (
        <ModalChangePasswordCertificate
          onClose={toggleModal('changePasswordCertificate')}
          isVisible={showModal.changePasswordCertificate}
          data={data}
        />
      )}
      {showModal.settingCertificate && (
        <ModalSettingCertificate
          onClose={toggleModal('settingCertificate')}
          isVisible={showModal.settingCertificate}
          data={data}
          onPressChangePassword={onPressChangePassword}
        />
      )}
    </View>
  );
};

export default ItemDigitalCertificate;
