import React, {useState, useCallback} from 'react';
import {
  useWindowDimensions,
  View,
  Modal,
  TouchableOpacity,
  Text,
  ViewStyle,
} from 'react-native';
import {GestureHandlerRootView} from 'react-native-gesture-handler';
import Animated, {
  useSharedValue,
  withSpring,
  useAnimatedStyle,
} from 'react-native-reanimated';
import styles from './styles';
import CustomDrawerContent from '../../navigation/SideMenu/components/CustomDrawerContent';
import {useNavigation} from '@react-navigation/native';
import {NavigationName} from '../../constants';

type Props = {
  renderOpenDrawer?: React.JSX.Element;
  container?: ViewStyle;
};

const DrawerCM = ({renderOpenDrawer, container}: Props) => {
  const navigation = useNavigation<any>();
  const [modalVisible, setModalVisible] = useState(false);
  const {width} = useWindowDimensions();
  const translateX = useSharedValue(-width);

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{translateX: translateX.value}],
  }));

  const toggleDrawer = () => {
    navigation.navigate(NavigationName.CustomDrawerContent);
  };

  return (
    <GestureHandlerRootView style={[styles.container]}>
      <View style={[container]}>
        {/* Gesture Detector cho phép kéo để mở/đóng */}
        {/* <Modal transparent visible={modalVisible} animationType="fade">
          <Animated.View
            style={[
              styles.drawer,
              animatedStyle,
              {
                width: width,
              },
            ]}>
            <CustomDrawerContent toggleDrawer={toggleDrawer} />
          </Animated.View>
        </Modal> */}

        {/* Nút mở Drawer */}
        {renderOpenDrawer ? (
          <TouchableOpacity onPress={toggleDrawer}>
            {renderOpenDrawer}
          </TouchableOpacity>
        ) : (
          <TouchableOpacity onPress={toggleDrawer} style={styles.openButton}>
            <Text style={styles.buttonText}>Open Menu</Text>
          </TouchableOpacity>
        )}
      </View>
    </GestureHandlerRootView>
  );
};

export default DrawerCM;
