import React, {useCallback, useEffect, useState} from 'react';
import {RefreshControl, ScrollView, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import Body from './components/Body';
import Header from './components/Header';
import OverviewDocument from './components/OverviewDocument';
import Statistical from './components/Statistical';
import styles from './styles';
import {useAppSelector} from '../../hook/useRedux';
import {useHomeServices} from '../../hook/apiHook/useHome';
import {String} from '../../constants';
import {IHomeScreen} from './interface';

const HomeScreen = () => {
  const user = useAppSelector(state => state.account.dataAccount);
  const [isRefreshing, setIsRefreshing] = React.useState(false);
  const [dataHomeScreen, setDataHomeScreen] = useState<IHomeScreen>({
    pending: 0,
    expire: 0,
    waitingResponse: 0,
    numberIncompleteDocument: 0,
    numberUserSubUnits: 0,
    numberUserOrganization: 0,
  });

  const HomeServices = useHomeServices();

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    try {
      const orgIn = user.orgIn;
      const owner = user.email;
      const [dataFindById, dataTransferData, dataInfo] = await Promise.all([
        HomeServices.fetchFindById(orgIn),
        HomeServices.fetchTransferData(owner),
        HomeServices.fetchInfo(orgIn, owner),
      ]);

      const data = {
        pending: dataTransferData.waiting || 0,
        expire: dataTransferData.dueDate || 0,
        waitingResponse: dataInfo.owner || 0,
        numberIncompleteDocument: dataInfo.orgIn || 0,
        numberUserSubUnits: dataFindById.numberUserAll || 0,
        numberUserOrganization: dataFindById.numberUserCurrent || 0,
      };
      setDataHomeScreen(data);
    } catch (error) {
      console.error('Error fetching data:', error);
    } finally {
      setIsRefreshing(false);
    }
  };

  const onRefreshData = () => {
    setIsRefreshing(true);
    getData();
  };

  return (
    <SafeAreaView edges={['top']} style={styles.ctnMain}>
      <Header />
      <ScrollView
        style={styles.mainContainer}
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefreshData} />
        }>
        <View style={styles.body}>
          <Body />
          <OverviewDocument dataHomeScreen={dataHomeScreen} />
          {user.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN) && (
            <Statistical dataHomeScreen={dataHomeScreen} />
          )}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

export default HomeScreen;
